function e(e){let t=e?.failed_cancellations?.length??0;return t>0?{toast:`error`,message:e?.message||`Failed to cancel ${t} order(s)`,refresh:!0}:e?.status===`success`?{toast:`success`,message:e.message||`All orders cancelled`,refresh:!0}:e?.status===`info`?{toast:`info`,message:e.message||`No open orders to cancel`,refresh:!1}:{toast:`error`,message:e?.message||`Failed to cancel all orders`,refresh:!0}}export{e as t};